(53,	'SylviaVamQR',	'a.d@marketsaletoday.com',	'{\"1\":{\"type\":\"name\",\"label\":\"Your Name\",\"value\":\"SylviaVamQR\"},\"2\":{\"type\":\"email\",\"label\":\"Your Email\",\"value\":\"a.d@marketsaletoday.com\"},\"3\":{\"type\":\"select\",\"label\":\"Topic\",\"value\":\"Your own custom criteria\"},\"4\":{\"type\":\"textarea\",\"label\":\"Message\",\"value\":\"&lt;b&gt;\\u041e\\u043d\\u043b\\u0430\\u0439\\u043d, \\u0411\\u0430\\u043d\\u043a\\u043e\\u0432\\u0441\\u043a\\u043e\\u0439 \\u041a\\u0430\\u0440\\u0442\\u043e\\u0439, \\u0413\\u043e\\u0441\\u0443\\u0441\\u043b\\u0443\\u0433\\u0438, \\u042f\\u043d\\u0434\\u0435\\u043a\\u0441 \\u0414\\u0435\\u043d\\u044c\\u0433\\u0438, \\u0421\\u0431\\u0435\\u0440\\u0431\\u0430\\u043d\\u043a \\u0418 \\u0414\\u0440[~nr~][~nl~] &lt;\\/b&gt; [~nr~][~nl~]----------------------------------- [~nr~][~nl~]\\u041c\\u0435\\u043d\\u044f \\u0441\\u0435\\u0439\\u0447\\u0430\\u0441 \\u043f\\u043b\\u044e\\u0449\\u0438\\u0442 \\u043e\\u0442 \\u0436\\u0435\\u043b\\u0430\\u043d\\u0438\\u044f \\u0431\\u044b\\u0442\\u044c \\u0440\\u044f\\u0434\\u043e\\u043c \\u0441 \\u0440\\u0435\\u0431\\u0435\\u043d\\u043a\\u043e\\u043c (\\u043e\\u0441\\u043e\\u0431\\u0435\\u043d\\u043d\\u043e \\u0432 \\u043f\\u0435\\u0440\\u0438\\u043e\\u0434 \\u0435\\u0433\\u043e \\u0431\\u043e\\u043b\\u0435\\u0437\\u043d\\u0438) \\u0441\\u043e \\u0441\\u043f\\u043e\\u043a\\u043e\\u0439\\u043d\\u043e\\u0439 \\u0441\\u043e\\u0432\\u0435\\u0441\\u0442\\u044c\\u044e, \\u0431\\u0435\\u0437 \\u043c\\u044b\\u0441\\u043b\\u0435\\u0439, \\u0447\\u0442\\u043e \\u044f \\u043a\\u043e\\u0433\\u043e-\\u0442\\u043e \\u043f\\u043e\\u0434\\u0432\\u043e\\u0436\\u0443 \\u0438 \\u0432 \\u0442\\u043e \\u0436\\u0435 \\u0432\\u0440\\u0435\\u043c\\u044f \\u043e\\u0442 \\u0436\\u0435\\u043b\\u0430\\u043d\\u0438\\u044f \\u0440\\u0430\\u0431\\u043e\\u0442\\u0430\\u0442\\u044c \\u0438 \\u0437\\u0430\\u0440\\u0430\\u0431\\u0430\\u0442\\u044b\\u0432\\u0430\\u0442\\u044c. \\u0411\\u044b\\u0432\\u0430\\u044e\\u0442 \\u0441\\u0438\\u0442\\u0443\\u0430\\u0446\\u0438\\u0438, \\u043a\\u043e\\u0433\\u0434\\u0430 \\u0438\\u043d\\u0432\\u0435\\u0441\\u0442\\u0438\\u0446\\u0438\\u043e\\u043d\\u043d\\u044b\\u0439 \\u0430\\u043a\\u0442\\u0438\\u0432 \\u0435\\u0449\\u0435 \\u043d\\u0435 \\u043f\\u0440\\u0438\\u043d\\u044f\\u0442 \\u043a \\u0431\\u0443\\u0445\\u00ad\\u0433\\u0430\\u043b\\u0442\\u0435\\u0440\\u0441\\u043a\\u043e\\u043c\\u0443 \\u0443\\u0447\\u0435\\u0442\\u0443 \\u0432 \\u043a\\u0430\\u0447\\u0435\\u0441\\u0442\\u0432\\u0435 \\u043e\\u0431\\u044a\\u0435\\u043a\\u0442\\u0430 \\u043e\\u0441\\u043d\\u043e\\u0432\\u043d\\u044b\\u0445 \\u0441\\u0440\\u0435\\u0434\\u0441\\u0442\\u0432 \\u0438\\u043b\\u0438 \\u0438\\u043c\\u0443\\u0449\\u0435\\u0441\\u0442\\u0432\\u0435\\u043d\\u00ad\\u043d\\u043e\\u0433\\u043e \\u043a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0441\\u0430; \\u043d\\u043e \\u0432\\u044b\\u043f\\u0443\\u0441\\u043a \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0446\\u0438\\u0438, \\u0432\\u044b\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u0435 \\u0440\\u0430\\u0431\\u043e\\u0442 \\u0438 \\u043e\\u043a\\u0430\\u0437\\u0430\\u043d\\u0438\\u0435 \\u0443\\u0441\\u043b\\u0443\\u0433 \\u043d\\u0430 \\u043d\\u0435\\u043c \\u0443\\u0436\\u0435 \\u043f\\u0440\\u043e\\u0438\\u0437\\u0432\\u043e\\u0434\\u044f\\u0442\\u0441\\u044f. \\u0411\\u044b\\u0432\\u0430\\u044e\\u0442 \\u0441\\u043b\\u0443\\u0447\\u0430\\u0438, \\u043a\\u043e\\u0433\\u0434\\u0430 \\u0437\\u0430\\u0451\\u043c\\u0449\\u0438\\u043a\\u0438 \\u0441\\u043e \\u0441\\u0442\\u0430\\u0436\\u0435\\u043c, \\u0440\\u0430\\u043d\\u0435\\u0435 \\u0434\\u043e\\u043f\\u0443\\u0441\\u043a\\u0430\\u0432\\u0448\\u0438\\u0435 \\u043f\\u0440\\u043e\\u0441\\u0440\\u043e\\u0447\\u043a\\u0438 \\u043f\\u043e \\u043a\\u0440\\u0435\\u0434\\u0438\\u0442\\u0430\\u043c, \\u0445\\u043e\\u0442\\u044f\\u0442 \\u043d\\u0430\\u0439\\u0442\\u0438 \\u0431\\u0430\\u043d\\u043a\\u0438, \\u043d\\u0435 \\u0437\\u0430\\u043f\\u04