(598,	'Angalét Ferenc',	'fercsi2003@gmail.com',	'{\"1\":{\"type\":\"name\",\"label\":\"N\\u00e9v\",\"value\":\"Angal\\u00e9t Ferenc\"},\"2\":{\"type\":\"email\",\"label\":\"E-mail\",\"value\":\"fercsi2003@gmail.com\"},\"3\":{\"type\":\"text\",\"label\":\"T\\u00e1rgy\",\"value\":\"Hib\\u00e1s term\\u00e9k \"},\"4\":{\"type\":\"textarea\",\"label\":\"\\u00dczenet\",\"value\":\"Sz\\u00e9p napot egy term\\u00e9k hib\\u00e1val kapcsolatosan \\u00edrok \\u00fczenetet \\u00f6n\\u00f6knek mert egyr\\u00e9szt el\\u00e9g f\\u00e9lelmetes hogy b\\u00e1rmikor berobbanhat az akkumul\\u00e1tort mivel folyamatosan hevit a mod fel tettem t\\u00f6lt\\u0151re \\u00e9s mikor levettem m\\u00e1r folyamatosan vil\\u00e1g\\u00edtott r\\u00e1 raktam a podot \\u00e9s sercegett \\u00e1lland\\u00f3an \\u00e9s nem mer\\u00fcl le mivel le vettem a podot \\u00edgy csak vil\\u00e1g\\u00edt \\u00e1lland\\u00f3an hogy ezzel kapcsolatosan valami megold\\u00e1s vagy csere vagy p\\u00e9nz vissza fizet\\u00e9s fenn \\u00e1ll esetleg?\"}}',	0,	'https://juicyvape.hu/',	'2022-04-07 09:26:21'),
(599,	'Farkas-Tóth Ivett',	'tothivett20@freemail.hu',	'{\"1\":{\"type\":\"name\",\"label\":\"N\\u00e9v\",\"value\":\"Farkas-T\\u00f3th Ivett\"},\"2\":{\"type\":\"email\",\"label\":\"E-mail\",\"value\":\"tothivett20@freemail.hu\"},\"3\":{\"type\":\"text\",\"label\":\"T\\u00e1rgy\",\"value\":\"K\\u00e9szletr\\u0151l \\u00e9rdekl\\u0151d\\u00e9s\"},\"4\":{\"type\":\"textarea\",\"label\":\"\\u00dczenet\",\"value\":\"J\\u00f3 napot! 0%-os Big Puffok \\u00e9rdekelnek. Sajnos l\\u00e1ttam csak 4 \\u00edz \\u00e9rhet\\u0151 el. A t\\u00f6bbi mikor lesz k\\u00e9szleten? K\\u00f6sz\\u00f6n\\u00f6m.\"}}',	0,	'https://juicyvape.hu/index.php?route=information/contact',	'2022-04-07 11:57:58'),
