(672,	'Buzsáki Richárd',	'ricsi.buzsaki@gmail.com',	'{\"1\":{\"type\":\"name\",\"label\":\"N\\u00e9v\",\"value\":\"Buzs\\u00e1ki Rich\\u00e1rd\"},\"2\":{\"type\":\"email\",\"label\":\"E-mail\",\"value\":\"ricsi.buzsaki@gmail.com\"},\"3\":{\"type\":\"text\",\"label\":\"T\\u00e1rgy\",\"value\":\"Rossz \\u00edz\"},\"4\":{\"type\":\"text\",\"label\":\"Rendel\\u00e9s sz\\u00e1ma\",\"value\":\"#27843\"},\"5\":{\"type\":\"textarea\",\"label\":\"Hibale\\u00edr\\u00e1s\",\"value\":\"A napokban rendeltem egy Aroma King Dark Knight - Lush Ice eldobhat\\u00f3 POD-ot, amit \\u00e1t is vettem, de sajnos azt tapasztaltam, hogy az \\u00edz le\\u00edr\\u00e1s az oldalon ami, mentol, j\\u00e9g (ezt csatoltam egy k\\u00e9p form\\u00e1j\\u00e1ban) nem felel meg a val\\u00f3s\\u00e1gnak \\u00e9s borzaszt\\u00f3an \\u00e9des \\u00edz\\u0171. \\u00d6r\\u00fcln\\u00e9k valamilyen jelleg\\u0171 kompenz\\u00e1l\\u00e1snak, mert kicsit f\\u00e9lrevezet\\u0151nek \\u00e9rzem, hogy egy mentol, j\\u00e9g \\u00edz\\u0171 term\\u00e9k ami egy ilyen kellemes friss mentolos \\u00edzt helyett egy teljesen \\u00e9des \\u00edzt ad ami sz\\u00e1momra fogyaszthatatlan.\"},\"6\":{\"type\":\"file\",\"label\":\"Csatolm\\u00e1ny (k\\u00e9p, vagy vide\\u00f3)\",\"value\":\"z.png\",\"url\":\"https:\\/\\/juicyvape.hu\\/index.php?route=journal3\\/form\\/download&amp;code=e6e510935e6b165305300182665dd320fdf79fa7\"}}',	0,	'https://juicyvape.hu/index.php?route=information/contact',	'2022-04-14 22:10:25'),
(673,	'Péter Vigh',	'petervigh18@gmail.com',	'{\"1\":{\"type\":\"name\",\"label\":\"N\\u00e9v\",\"value\":\"P\\u00e9ter Vigh\"},\"2\":{\"type\":\"email\",\"label\":\"E-mail\",\"value\":\"petervigh18@gmail.com\"},\"3\":{\"type\":\"text\",\"label\":\"T\\u00e1rgy\",\"value\":\"Tank\"},\"4\":{\"type\":\"textarea\",\"label\":\"\\u00dczenet\",\"value\":\"Hell\\u00f3 olyan k\\u00e9rd\\u00e9sem lenne hogy n\\u00e9ztem n\\u00e1latok a steam crave aromizer tit\\u00e1n v2 tankot 22 \\u00e9rt ahoz tartozik a du\\u00e1l mesh vagy nem vagy k\\u00fcl\\u00f6n lehet e rendelni t\\u0151letek? \"}}',	0,	'https://juicyvape.hu/index.php?route=information/contact',	'2022-04-16 17:52:19'),
