(1800,	'Lőrik László',	'loriklacika97@gmail.com',	'{\"1\":{\"type\":\"name\",\"label\":\"N\\u00e9v\",\"value\":\"L\\u0151rik L\\u00e1szl\\u00f3\"},\"2\":{\"type\":\"tel\",\"label\":\"Telefonsz\\u00e1m\",\"value\":\"06301862716\"},\"3\":{\"type\":\"email\",\"label\":\"E-mail\",\"value\":\"loriklacika97@gmail.com\"},\"4\":{\"type\":\"text\",\"label\":\"T\\u00e1rgy\",\"value\":\"Kever\\u00e9si ar\\u00e1ny\"},\"5\":{\"type\":\"text\",\"label\":\"Rendel\\u00e9s sz\\u00e1ma\",\"value\":\"Nincs\"},\"6\":{\"type\":\"textarea\",\"label\":\"\\u00dczenet\",\"value\":\"\\u00dcdv, [~nr~][~nl~][~nr~][~nl~]A k\\u00f6vetkez\\u0151ket raktam a kos\\u00e1rba. Az lenne a k\\u00e9rd\\u00e9sem hogy ezekhez kell e m\\u00e9g valamit v\\u00e1s\\u00e1rolnom. [~nr~][~nl~]Aroma Center-Watermelon Twist 12ml [~nr~][~nl~]100ml vg b\\u00e1zis [~nr~][~nl~]100ml pl b\\u00e1zis [~nr~][~nl~]Illetve ha j\\u00f3k akkor hogyan kell \\u00f6ssze kevernem?[~nr~][~nl~][~nr~][~nl~]K\\u00f6sz\\u00f6n\\u00f6m el\\u0151re is![~nr~][~nl~][~nr~][~nl~]\\u00dcdv, [~nr~][~nl~]L\\u00e1szl\\u00f3 \"}}',	0,	'https://aromacenter.hu/index.php?route=information/contact',	'2025-08-26 16:43:18'),
(1801,	'Lencskó János',	'janoslencsko@gmail.com',	'{\"1\":{\"type\":\"name\",\"label\":\"N\\u00e9v\",\"value\":\"Lencsk\\u00f3 J\\u00e1nos\"},\"2\":{\"type\":\"tel\",\"label\":\"Telefonsz\\u00e1m\",\"value\":\"06204603066\"},\"3\":{\"type\":\"email\",\"label\":\"E-mail\",\"value\":\"janoslencsko@gmail.com\"},\"4\":{\"type\":\"text\",\"label\":\"T\\u00e1rgy\",\"value\":\"Rendel\\u00e9s \"},\"5\":{\"type\":\"text\",\"label\":\"Rendel\\u00e9s sz\\u00e1ma\",\"value\":\"105916\"},\"6\":{\"type\":\"textarea\",\"label\":\"\\u00dczenet\",\"value\":\"Tisztelt Aromacenter \\u00e1ruh\\u00e1z.  Sajn\\u00e1lom de most sem kaptam meg a rendel\\u00e9semet. Szeretn\\u00e9m vissza k\\u00e9rni a befizet\\u00e9t \\u00f6sszeget. [~nr~][~nl~]K\\u00f6sz\\u00f6n\\u00f6m sz\\u00e9pen. [~nr~][~nl~]\\u00dcdv.  Lencsk\\u00f3 J\\u00e1nos [~nr~][~nl~]\"}}',	0,	'https://aromacenter.hu/index.php?route=information/contact',	'2025-08-26 22:26:08'),
(1802,	'Wittmann Csaba',	'wwwhitem@gmail.com',	'{\"1\":{\"type\":\"name\",\"label\":\"N\\u00e9v\",\"value\":\"Wittmann Csaba\"},\"2\":{\"type\":\"tel\",\"label\":\"Telefonsz\\u00e1m\",\"value\":\"06209373319\"},\"3\":{\"type\":\"email\",\"label\":\"E-mail\",\"value\":\"wwwhitem@gmail.com\"},\"4\":{\"type\":\"text\",\"label\":\"T\\u00e1rgy\",\"value\":\"Rendel\\u00e9s\"},\"5\":{\"type\":\"text\",\"label\":\"Rendel\\u00e9s sz\\u00e1ma\",\"value\":\"#106798\"},\"6\":{\"type\":\"textarea\",\"label\":\"\\u00dczenet\",\"value\":\"\\u00dcdv\\u00f6zl\\u00f6m! \\u00c9rdekl\\u0151dn\\u00e9k a rendel\\u00e9semmel kapcsolatban... 20.-\\u00e1n adtam le a rendel\\u00e9sem  kaptam egy sikeres rendel\\u00e9s emailt \\u00e9s az\\u00f3ta semmit ....  mikor sz\\u00e1m\\u00edthatok a csomagra ? \"}}',	0,	'https://aromacenter.hu/index.php?route=information/contact',	'2025-08-27 15:31:12'),
(1803,	'Sági-Saska Attila ',	'sagisaskaattila@gmail.com',	'{\"1\":{\"type\":\"name\",\"label\":\"N\\u00e9v\",\"value\":\"S\\u00e1gi-Saska Attila \"},\"2\":{\"type\":\"tel\",\"label\":\"Telefonsz\\u00e1m\",\"value\":\"06705755854\"},\"3\":{\"type\":\"email\",\"label\":\"E-mail\",\"value\":\"sagisaskaattila@gmail.com\"},\"4\":{\"type\":\"text\",\"label\":\"T\\u00e1rgy\",\"value\":\"Rendel\\u00e9s\"},\"5\":{\"type\":\"text\",\"label\":\"Rendel\\u00e9s sz\\u00e1ma\",\"value\":\"106873\"},\"6\":{\"type\":\"textarea\",\"label\":\"\\u00dczenet\",\"value\":\"\\u00dcdv \\u00e9rdekl\\u0151dni szeretn\\u00e9k hogy a fent megadott megrendel\\u00e9si sz\\u00e1mmal rendelkez\\u0151 rendel\\u00e9sem mikor ker\\u00fcl k\\u00e9zbes\\u00edt\\u00e9sre.El\\u0151re is k\\u00f6sz\\u00f6n\\u00f6m.\"}}',	0,	'https://aromacenter.hu/index.php?route=information/contact',	'2025-08-27 22:06:10'),
(1804,	'Nagy Sándor',	'nagy.sandor.janos@gmail.com',	'{\"1\":{\"type\":\"name\",\"label\":\"N\\u00e9v\",\"value\":\"Nagy S\\u00e1ndor\"},\"2\":{\"type\":\"tel\",\"label\":\"Telefonsz\\u00e1m\",\"value\":\"+36306423096\"},\"3\":{\"type\":\"email\",\"label\":\"E-mail\",\"value\":\"nagy.sandor.janos@gmail.com\"},\"4\":{\"type\":\"text\",\"label\":\"T\\u00e1rgy\",\"value\":\"Sz\\u00e1ll\\u00edt\\u00e1si \\u00e9rdekl\\u0151d\\u00e9s\"},\"5\":{\"type\":\"text\",\"label\":\"Rendel\\u00e9s sz\\u00e1ma\",\"value\":\"107238\"},\"6\":{\"type\":\"textarea\",\"label\":\"\\u00dczenet\",\"value\":\"Tisztelt AromaCenter![~nr~][~nl~][~nr~][~nl~]Szeretn\\u00e9k \\u00e9rdekl\\u0151dni, hogy van e lehet\\u0151s\\u00e9g r\\u00e1, hogy a mai napon leadott 107238 sz\\u00e1m\\u00fa rendel\\u00e9sem m\\u00e9g ma felad\\u00e1sra ker\\u00fclj\\u00f6n a GLS sz\\u00e1m\\u00e1ra?[~nr~][~nl~][~nr~][~nl~]V\\u00e1laszukat el\\u0151re is k\\u00f6sz\\u00f6n\\u00f6m![~nr~][~nl~][~nr~][~nl~]\\u00dcdv\\u00f6zlettel,[~nr~][~nl~]Nagy S\\u00e1ndor\"}}',	0,	'https://aromacenter.hu/index.php?route=information/contact',	'2025-08-28 12:57:35'),
(1805,	'Iro Balazs',	'iro.cyanogen@gmail.com',	'{\"1\":{\"type\":\"name\",\"label\":\"N\\u00e9v\",\"value\":\"Iro Balazs\"},\"2\":{\"type\":\"tel\",\"label\":\"Telefonsz\\u00e1m\",\"value\":\"+36305740225\"},\"3\":{\"type\":\"email\",\"label\":\"E-mail\",\"value\":\"iro.cyanogen@gmail.com\"},\"4\":{\"type\":\"text\",\"label\":\"T\\u00e1rgy\",\"value\":\"Erdeklodes a rendelesrol\"},\"5\":{\"type\":\"text\",\"label\":\"Rendel\\u00e9s sz\\u00e1ma\",\"value\":\"#106812\"},\"6\":{\"type\":\"textarea\",\"label\":\"\\u00dczenet\",\"value\":\"Sziasztok![~nr~][~nl~][~nr~][~nl~]Szeretnek erdeklodni, hogy a 8 napja leadott rendelesre mikor szamithatok?[~nr~][~nl~][~nr~][~nl~]Balazs\"}}',	0,	'https://aromacenter.hu/index.php?route=information/contact',	'2025-08-28 14:45:03'),
(1806,	'Barta Péter',	'civicvti02@icloud.com',	'{\"1\":{\"type\":\"name\",\"label\":\"N\\u00e9v\",\"value\":\"Barta P\\u00e9ter\"},\"2\":{\"type\":\"tel\",\"label\":\"Telefonsz\\u00e1m\",\"value\":\"06301148445\"},\"3\":{\"type\":\"email\",\"label\":\"E-mail\",\"value\":\"civicvti02@icloud.com\"},\"4\":{\"type\":\"text\",\"label\":\"T\\u00e1rgy\",\"value\":\"Rendel\\u00e9s \\u00c1tv\\u00e9tel\"},\"5\":{\"type\":\"text\",\"label\":\"Rendel\\u00e9s sz\\u00e1ma\",\"value\":\"00\"},\"6\":{\"type\":\"textarea\",\"label\":\"\\u00dczenet\",\"value\":\"Kedves aromacenter. \\u00c9rdekl\\u0151dni szeretn\\u00e9k ,hogy amennyiben minden kin\\u00e9zett term\\u00e9k van k\\u00e9szleten , van r\\u00e1 es\\u00e9ly ,hogy a rendel\\u00e9sem szem\\u00e9lyesen \\u00e1ttudjam venni? El\\u0151re is k\\u00f6sz\\u00f6n\\u00f6m a v\\u00e1laszt!\"}}',	0,	'https://aromacenter.hu/index.php?route=information/contact',	'2025-08-29 06:58:57'),
(1807,	'Kundár Kristóf Imre',	'kundar.kristof@gmail.com',	'{\"1\":{\"type\":\"name\",\"label\":\"N\\u00e9v\",\"value\":\"Kund\\u00e1r Krist\\u00f3f Imre\"},\"2\":{\"type\":\"tel\",\"label\":\"Telefonsz\\u00e1m\",\"value\":\"+36206288404\"},\"3\":{\"type\":\"email\",\"label\":\"E-mail\",\"value\":\"kundar.kristof@gmail.com\"},\"4\":{\"type\":\"text\",\"label\":\"T\\u00e1rgy\",\"value\":\"Rendel\\u00e9s\"},\"5\":{\"type\":\"text\",\"label\":\"Rendel\\u00e9s sz\\u00e1ma\",\"value\":\"107213\"},\"6\":{\"type\":\"textarea\",\"label\":\"\\u00dczenet\",\"value\":\"Tisztelt AromaCenter,[~nr~][~nl~][~nr~][~nl~]08.27.-\\u00e9n leadtam \\u00d6n\\u00f6kh\\u00f6z egy rendel\\u00e9st (107213). [~nr~][~nl~][~nr~][~nl~]Meg is kaptam a visszaigazol\\u00e1st a rendel\\u00e9s megl\\u00e9t\\u00e9r\\u0151l, de az\\u00f3ta nem kaptam semmilyen inform\\u00e1ci\\u00f3t a csomagom st\\u00e1tusz\\u00e1r\\u00f3l.[~nr~][~nl~][~nr~][~nl~]\\u00c9rdekl\\u0151dn\\u00e9k, hogy merre j\\u00e1r a csomagom.[~nr~][~nl~][~nr~][~nl~]\\u00dcdv\\u00f6zlettel,[~nr~][~nl~]Kund\\u00e1r Krist\\u00f3f Imre[~nr~][~nl~]+36206288404\"}}',	0,	'https://aromacenter.hu/index.php?route=information/contact',	'2025-08-29 10:39:57'),
(1808,	'Fedeles Éva Viktória',	'evavictoria87@gmail.com',	'{\"1\":{\"type\":\"name\",\"label\":\"N\\u00e9v\",\"value\":\"Fedeles \\u00c9va Vikt\\u00f3ria\"},\"2\":{\"type\":\"tel\",\"label\":\"Telefonsz\\u00e1m\",\"value\":\"06303665992\"},\"3\":{\"type\":\"email\",\"label\":\"E-mail\",\"value\":\"evavictoria87@gmail.com\"},\"4\":{\"type\":\"text\",\"label\":\"T\\u00e1rgy\",\"value\":\"Egyeztet\\u00e9s\"},\"5\":{\"type\":\"text\",\"label\":\"Rendel\\u00e9s sz\\u00e1ma\",\"value\":\"#106629\"},\"6\":{\"type\":\"textarea\",\"label\":\"\\u00dczenet\",\"value\":\"Tisztelt C\\u00edmzett![~nr~][~nl~][~nr~][~nl~]Most l\\u00e1ttam a rendel\\u00e9s \\u00e1llapot\\u00e1n\\u00e1l, hogy egyeztet\\u00e9s sz\\u00fcks\\u00e9ges, de err\\u0151l nem kaptam emailt, rendel\\u00e9s ut\\u00e1n azonnal m\\u00f3dos\\u00edtottam az e-mail c\\u00edmemet, mert v\\u00e9letlen\\u00fcl rosszul \\u00edrtam be, rem\\u00e9lem a foxpostnak m\\u00e1r ez az e-mail c\\u00edm fog tov\\u00e1bb\\u00edt\\u00e1sra ker\\u00fclni. Az egyeztet\\u00e9ssel kapcsolatban nem k\\u00e9r\\u00fcnk csere term\\u00e9ket, szeretn\\u00e9nk megkapni a rendel\\u00e9st a hi\\u00e1nyz\\u00f3 term\\u00e9k n\\u00e9lk\\u00fcl.[~nr~][~nl~]K\\u00f6sz\\u00f6nettel:[~nr~][~nl~]Fedeles Vikt\\u00f3ria\"}}',	0,	'https://aromacenter.hu/index.php?route=information/contact',	'2025-08-29 14:30:08'),
(1809,	'Sági-Saska Attila ',	'sagisaskaattila@gmail.com',	'{\"1\":{\"type\":\"name\",\"label\":\"N\\u00e9v\",\"value\":\"S\\u00e1gi-Saska Attila \"},\"2\":{\"type\":\"tel\",\"label\":\"Telefonsz\\u00e1m\",\"value\":\"06705755854\"},\"3\":{\"type\":\"email\",\"label\":\"E-mail\",\"value\":\"sagisaskaattila@gmail.com\"},\"4\":{\"type\":\"text\",\"label\":\"T\\u00e1rgy\",\"value\":\"Rendel\\u00e9s pontos\\u00edt\\u00e1s\"},\"5\":{\"type\":\"text\",\"label\":\"Rendel\\u00e9s sz\\u00e1ma\",\"value\":\"106873\"},\"6\":{\"type\":\"textarea\",\"label\":\"\\u00dczenet\",\"value\":\"\\u00dcdv a fent eml\\u00edtett rendel\\u00e9s fizetve van m\\u00e9gis ut\\u00e1nv\\u00e9tes sz\\u00e1ll\\u00edt\\u00e1sr\\u00f3l kaptam \\u00e9rtes\\u00edt\\u00e9st.Mi a tehend\\u0151 a tov\\u00e1bbiakban?K\\u00e9rn\\u00e9k egy telefonos megkeres\\u00e9st a rendel\\u00e9s lebonyol\\u00edt\\u00e1sa \\u00e9rdek\\u00e9ben k\\u00f6sz\\u00f6n\\u00f6m.\"}}',	0,	'https://aromacenter.hu/index.php?route=information/contact',	'2025-08-31 19:27:31');
